<template><section class="workspace-view" data-view-panel="shop"><div class="page-heading"><span class="eyebrow background-readable">COMMUNITY MARKET / 03</span><h2 class="background-readable">周边商城</h2><p class="background-readable">把喜欢的曲目和街机记忆带回桌面。</p></div><div class="shop-toolbar"><button v-for="item in ['全部','徽章','服饰','桌面物件']" :key="item" class="filter-chip" :class="{ active: item === '全部' }" type="button">{{ item }}</button></div><div class="product-grid"><article v-for="item in [{name:'节奏徽章套装',desc:'限定活动纪念',price:'¥ 39',class:''},{name:'街机节奏桌垫',desc:'防滑织物材质',price:'¥ 89',class:'purple'},{name:'曲目收藏卡',desc:'随机 3 张',price:'¥ 19',class:'blue'}]" :key="item.name" class="product-card"><div class="product-art" :class="item.class">商品图<br />{{ item.class === 'purple' ? '02' : item.class === 'blue' ? '03' : '01' }}</div><div><h3>{{ item.name }}</h3><p>{{ item.desc }}</p><strong>{{ item.price }}</strong></div></article></div></section></template>
